import type { paths } from '@prisma/management-api-sdk';
import * as Data from 'effect/Data';
import * as Effect from 'effect/Effect';
import { type ManagementApiClient, ManagementClient } from './client.ts';
import { call, callVoid, PrismaApiError } from './http.ts';
import { collectPages, drivePages } from './pagination.ts';

/** The region ids the Management API accepts for a new Project — the platform's published contract, not a Composer-owned list. */
export type ProjectRegion = NonNullable<
  NonNullable<paths['/v1/projects']['post']['requestBody']>['content']['application/json']['region']
>;

export interface ResolveContainerOptions {
  /** The workspace to resolve the Project in. */
  readonly workspaceId: string;
  /** The app's name — the root `module("<name>", …)` name, or `--name`. */
  readonly appName: string;
  /** The Composer environment. `production` is the Project's default Branch; any other name is the Branch with that `gitName`. */
  readonly environment: string;
  /** Create the Project/Branch if absent (default `true`). `false` finds only — used by `destroy`. */
  readonly ensure?: boolean;
  /**
   * The region to stamp on the Project at creation time. Required when creating a new Project
   * (`ensure: true` and no matching Project found). Omit for find-only (`ensure: false`) or when
   * the Project already exists — the platform's stored default region is used then.
   */
  readonly region?: ProjectRegion;
}

/** Raised with `ensure: false` when the app's Project (or a named environment's Branch) doesn't exist. */
export class ContainerNotFoundError extends Data.TaggedError('ContainerNotFoundError')<{
  readonly appName: string;
  readonly environment?: string;
}> {}

/** The environment that maps to the Project's default Branch. */
export const PRODUCTION_ENVIRONMENT = 'production';

/** Whether `environment` maps to the Project's default Branch rather than a Branch of its own. */
export function isProductionEnvironment(environment: string): boolean {
  return environment === PRODUCTION_ENVIRONMENT;
}

/** Raised when a name other than `production` resolves to the Project's default Branch, which would make it production under a second name. */
export class DefaultBranchUnderAnotherNameError extends Data.TaggedError(
  'DefaultBranchUnderAnotherNameError',
)<{
  readonly environment: string;
  readonly branchId: string;
}> {
  override get message(): string {
    return (
      `The environment "${this.environment}" names the Branch ${this.branchId}, which is this ` +
      "Project's default Branch, so that Branch is production. " +
      `Use the environment ${PRODUCTION_ENVIRONMENT} for it, and another name for a separate environment.`
    );
  }
}

export interface ResolvedContainer {
  readonly projectId: string;
  /** Set only for an environment other than `production`. */
  readonly branchId?: string;
  /** Set only for `production`: the project's default Branch's id (a read; the Branch is never created here). */
  readonly defaultBranchId?: string;
}

interface ProjectSummary {
  readonly id: string;
  readonly name: string;
  readonly createdAt: string;
  readonly workspace: { readonly id: string };
  /** Set on projects created with a logical id; null or absent on older projects. */
  readonly logicalId?: string | null;
}

const listAllProjects = (
  client: ManagementApiClient,
): Effect.Effect<readonly ProjectSummary[], PrismaApiError> =>
  collectPages('projects', (cursor) =>
    call(() =>
      client.GET('/v1/projects', {
        params: { query: cursor === undefined ? {} : { cursor } },
      }),
    ),
  );

/**
 * Workspace ids circulate in two shapes: `wksp_`-prefixed and bare. Compare
 * bare-to-bare so a `wksp_`-prefixed API id still matches a bare configured
 * one (the same normalization `state/bootstrap.ts` applies to the same
 * `/v1/projects` listing).
 */
const bareWorkspaceId = (id: string): string =>
  id.startsWith('wksp_') ? id.slice('wksp_'.length) : id;

/**
 * Finds the app's Project by logical id or name in the workspace, creating
 * one if absent. Logical id match (exact, workspace-unique) is preferred over
 * display-name match (oldest-wins fallback for projects without a logical id).
 * Creates one if none match, unless `ensure` is `false` (find-only —
 * `destroy`), in which case an absent Project fails with
 * `ContainerNotFoundError`. No ownership marker and no `--project` override
 * (both deferred — see ADR-0019).
 */
const resolveProject = (
  client: ManagementApiClient,
  workspaceId: string,
  appName: string,
  ensure: boolean,
  region: ProjectRegion | undefined,
): Effect.Effect<string, PrismaApiError | ContainerNotFoundError> =>
  Effect.gen(function* () {
    const projects = yield* listAllProjects(client);
    const workspaceProjects = projects.filter(
      (p) => bareWorkspaceId(p.workspace.id) === bareWorkspaceId(workspaceId),
    );

    const logicalIdMatch = workspaceProjects.find(
      (p) => p.logicalId != null && p.logicalId === appName,
    );
    if (logicalIdMatch !== undefined) return logicalIdMatch.id;

    const nameMatch = workspaceProjects
      .filter((p) => p.name === appName)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt))[0];
    if (nameMatch !== undefined) return nameMatch.id;

    if (!ensure) return yield* Effect.fail(new ContainerNotFoundError({ appName }));

    if (region === undefined) {
      return yield* Effect.fail(
        new PrismaApiError({
          status: 0,
          message:
            `project "${appName}" does not exist yet and no deploy region is configured. ` +
            "Set the region via prismaCloud({ region: '<id>' }) in your config, or set the " +
            'PRISMA_REGION environment variable',
        }),
      );
    }

    // Without a default database the platform writes no DATABASE_URL for the project.
    // User actors get a 403 for createDatabase: false; deploys use a service token, which is allowed.
    const created = yield* call(() =>
      client.POST('/v1/projects', {
        body: { name: appName, workspaceId, createDatabase: false, logicalId: appName, region },
      }),
    ).pipe(
      Effect.catch((err) =>
        err.status === 409
          ? Effect.fail(
              new PrismaApiError({
                status: 409,
                message:
                  'a project with this name already exists in the workspace; rename your Composer module or free the name.',
              }),
            )
          : Effect.fail(err),
      ),
    );
    return created.data.id;
  });

/**
 * The project's implicit default Branch — every live Project owns exactly
 * one (a platform invariant). The list endpoint has no `isDefault` filter,
 * so this pages through the Branches (bounded — drivePages) and returns as
 * soon as a page contains it. Never creates one: its absence means the
 * platform's invariant is broken, which is not something a deploy can
 * repair.
 */
export const resolveDefaultBranchId = (
  client: ManagementApiClient,
  projectId: string,
): Effect.Effect<string, PrismaApiError> =>
  Effect.gen(function* () {
    let found: string | undefined;
    yield* drivePages(
      `branches of project ${projectId}`,
      (cursor) =>
        call(() =>
          client.GET('/v1/projects/{projectId}/branches', {
            params: { path: { projectId }, query: cursor === undefined ? {} : { cursor } },
          }),
        ),
      (data) => {
        found = data.find((b) => b.isDefault)?.id;
        return found !== undefined;
      },
    );
    if (found !== undefined) return found;
    return yield* Effect.fail(
      new PrismaApiError({
        status: 0,
        message: `project ${projectId} has no default Branch — the platform guarantees every live Project owns one; contact support.`,
      }),
    );
  });

interface FoundBranch {
  readonly id: string;
  readonly isDefault: boolean;
}

const findBranch = (
  client: ManagementApiClient,
  projectId: string,
  gitName: string,
): Effect.Effect<FoundBranch | undefined, PrismaApiError> =>
  call(() =>
    client.GET('/v1/projects/{projectId}/branches', {
      params: { path: { projectId }, query: { gitName } },
    }),
  ).pipe(
    Effect.map((page) => {
      const branch = page.data[0];
      return branch === undefined ? undefined : { id: branch.id, isDefault: branch.isDefault };
    }),
  );

/**
 * Finds the environment's Branch by its exact `gitName`, creating it if absent
 * unless `ensure` is `false` (find-only — `destroy`), in which case an
 * absent Branch fails with `ContainerNotFoundError`. A `gitName` that finds
 * the default Branch fails with `DefaultBranchUnderAnotherNameError`. The Management API has
 * no server-side "create-or-return" idempotency (`POST
 * /v1/projects/:id/branches` 409s on a duplicate `gitName`, with no request
 * field to make that a no-op), so idempotency is client-side: observe
 * first, and on a racing 409 from create, re-observe rather than fail.
 */
const resolveBranch = (
  client: ManagementApiClient,
  projectId: string,
  gitName: string,
  appName: string,
  ensure: boolean,
): Effect.Effect<
  string,
  PrismaApiError | ContainerNotFoundError | DefaultBranchUnderAnotherNameError
> =>
  Effect.gen(function* () {
    const existing = yield* findBranch(client, projectId, gitName);
    if (existing !== undefined) return yield* refuseDefaultBranch(existing, gitName);

    if (!ensure) {
      return yield* Effect.fail(new ContainerNotFoundError({ appName, environment: gitName }));
    }

    return yield* call(() =>
      client.POST('/v1/projects/{projectId}/branches', {
        params: { path: { projectId } },
        body: { gitName },
      }),
    ).pipe(
      Effect.map((r) => r.data.id),
      Effect.catch((err) =>
        err.status === 409
          ? Effect.gen(function* () {
              const found = yield* findBranch(client, projectId, gitName);
              if (found === undefined) return yield* Effect.fail(err);
              return yield* refuseDefaultBranch(found, gitName);
            })
          : Effect.fail(err),
      ),
    );
  });

const refuseDefaultBranch = (
  branch: FoundBranch,
  gitName: string,
): Effect.Effect<string, DefaultBranchUnderAnotherNameError> =>
  branch.isDefault === true
    ? Effect.fail(
        new DefaultBranchUnderAnotherNameError({ environment: gitName, branchId: branch.id }),
      )
    : Effect.succeed(branch.id);

/**
 * Resolves the two containers an environment's deploy runs into (ADR-0019):
 * the app's **Project**, found-or-created by name, and its **Branch**. The
 * environment `production` is the Project's default Branch, read into
 * `defaultBranchId` and never created; `branchId` is omitted. Any other name
 * is the Branch with that `gitName`, found-or-created into `branchId`. With
 * `ensure: false` (`destroy`), nothing is created — an absent Project or
 * Branch fails with `ContainerNotFoundError` instead.
 */
export const resolveContainer = (
  opts: ResolveContainerOptions,
): Effect.Effect<
  ResolvedContainer,
  PrismaApiError | ContainerNotFoundError | DefaultBranchUnderAnotherNameError,
  ManagementClient
> =>
  Effect.gen(function* () {
    const client = yield* ManagementClient;
    const ensure = opts.ensure ?? true;
    const projectId = yield* resolveProject(
      client,
      opts.workspaceId,
      opts.appName,
      ensure,
      opts.region,
    );
    if (isProductionEnvironment(opts.environment)) {
      const defaultBranchId = yield* resolveDefaultBranchId(client, projectId);
      return { projectId, defaultBranchId };
    }

    const branchId = yield* resolveBranch(
      client,
      projectId,
      opts.environment,
      opts.appName,
      ensure,
    );
    return { projectId, branchId };
  });

/**
 * Soft-deletes a Branch. Tolerates a 404 (already gone). The API refuses if
 * the Branch still has live members or is the production/default Branch —
 * that surfaces as a `PrismaApiError`.
 */
export const deleteBranch = (
  branchId: string,
): Effect.Effect<void, PrismaApiError, ManagementClient> =>
  Effect.gen(function* () {
    const client = yield* ManagementClient;
    yield* callVoid(() =>
      client.DELETE('/v1/branches/{branchId}', { params: { path: { branchId } } }),
    );
  });

/**
 * Deletes a Project. Tolerates a 404 (already gone). The API refuses with a
 * 400 if the Project still has live dependencies (e.g. another environment's
 * Branch/resources) — that surfaces as a `PrismaApiError`.
 */
export const deleteProject = (
  projectId: string,
): Effect.Effect<void, PrismaApiError, ManagementClient> =>
  Effect.gen(function* () {
    const client = yield* ManagementClient;
    yield* callVoid(() =>
      client.DELETE('/v1/projects/{id}', { params: { path: { id: projectId } } }),
    );
  });
